// Remove raster dust and pinholes before any pixel boundary becomes a metal return.
export function cleanArtworkMask(input,w,h){const mask=Uint8Array.from(input);
 // Keep the original letter separations and counters. Global dilation merged JPEG letters.
 const labels=new Int32Array(mask.length),areas=[0],queue=new Int32Array(mask.length);let label=0,total=mask.reduce((n,v)=>n+v,0);const neighbors=i=>{const x=i%w,y=Math.floor(i/w),out=[];if(x)out.push(i-1);if(x<w-1)out.push(i+1);if(y)out.push(i-w);if(y<h-1)out.push(i+w);return out;};
 for(let i=0;i<mask.length;i++)if(mask[i]&&!labels[i]){label++;let head=0,tail=1;queue[0]=i;labels[i]=label;while(head<tail){const k=queue[head++];for(const j of neighbors(k))if(mask[j]&&!labels[j]){labels[j]=label;queue[tail++]=j;}}areas.push(tail);}
 const minimum=Math.max(4,Math.round(total*.00008));for(let i=0;i<mask.length;i++)if(mask[i]&&areas[labels[i]]<minimum)mask[i]=0;
 const seen=new Uint8Array(mask.length);for(let i=0;i<mask.length;i++)if(!mask[i]&&!seen[i]){let head=0,tail=1,edge=false,owner=0,owners=new Set();queue[0]=i;seen[i]=1;while(head<tail){const k=queue[head++],x=k%w,y=Math.floor(k/w);if(x===0||y===0||x===w-1||y===h-1)edge=true;for(const j of neighbors(k)){if(mask[j]){owner=labels[j];owners.add(owner);}else if(!seen[j]){seen[j]=1;queue[tail++]=j;}}}if(!edge&&(owners.size>1||tail<Math.max(2,(areas[owner]||0)*.002)))for(let j=0;j<tail;j++)mask[queue[j]]=1;}
 return mask;
}
export function clippedReturnRings(contours,thickness,C){const scale=1e6;const paths=contours.map((points,i)=>{const p=points.map(([x,y])=>({X:Math.round(x*scale),Y:Math.round(y*scale)}));if(C.Clipper.Orientation(p)!==(i===0))p.reverse();return p;});const offset=new C.ClipperOffset(2,Math.max(5,thickness*scale*.015));offset.AddPaths(paths,C.JoinType.jtRound,C.EndType.etClosedPolygon);const inner=new C.Paths();offset.Execute(inner,-thickness*scale);const clipping=new C.Clipper();clipping.AddPaths(paths,C.PolyType.ptSubject,true);if(inner.length)clipping.AddPaths(inner,C.PolyType.ptClip,true);const tree=new C.PolyTree();clipping.Execute(C.ClipType.ctDifference,tree,C.PolyFillType.pftNonZero,C.PolyFillType.pftNonZero);const output=[],points=node=>C.Clipper.CleanPolygon(node.Contour(),Math.max(2,thickness*scale*.035)).map(p=>[p.X/scale,p.Y/scale]);const visit=node=>{if(node.Contour().length&&!node.IsHole())output.push({points:points(node),holes:node.Childs().filter(c=>c.IsHole()).map(points)});node.Childs().forEach(visit);};visit(tree);return output;}
